"""Acquire original width evidence from a source-hashed Native alley operator.

The operator supplies actual map/actor readback and original frames. Requested
parking widths and other-vehicle positions are never used as observed values.
"""
from __future__ import annotations

import hashlib
import json
import math
import os
from pathlib import Path
import shutil
import tempfile
import zipfile

from alley_width_construction import VARIANTS, build_plan
from width_measurement import ASSIGNMENT, measure_saved

CAMERAS = frozenset(("overview", "approach", "reference_corner", "driver_reference"))
FRAMES = 900


def _write(path, value):
    raw = (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()
    path.write_bytes(raw)
    return hashlib.sha256(raw).hexdigest()


def capture(operator, case_id, output, after_tick=None):
    """Capture via injected operator; fail closed on absent original readback."""
    variant = case_id.removeprefix(ASSIGNMENT + "__")
    if not case_id.startswith(ASSIGNMENT + "__") or variant not in VARIANTS:
        raise ValueError("unknown exact alley-width case")
    destination = Path(output)
    if destination.exists():
        raise ValueError("refusing to replace original attempt")
    if after_tick is not None and not callable(after_tick):
        raise ValueError("same-tick Core graph callback missing")
    geometry = operator.get_map_packet(case_id)
    if geometry.get("case_id") != case_id or geometry.get("source_kind") != "original_native_geometry":
        raise ValueError("original source-gated alley packet missing")
    if geometry.get("alley_kind") != "other_alley" or geometry.get("public_highway_status") is not True:
        raise ValueError("qualifying other alley source review missing")
    if variant == "ordinance_otherwise" and geometry.get("ordinance_status") != "otherwise_provides":
        raise ValueError("reviewed local ordinance exception source missing")
    if not geometry.get("map_sha256") or not geometry.get("ego_blueprint_source") or not geometry.get("ego_dimensions_source"):
        raise ValueError("original map or ego blueprint source missing")
    map_bytes = operator.get_opendrive_bytes()
    if not isinstance(map_bytes, bytes) or hashlib.sha256(map_bytes).hexdigest() != geometry["map_sha256"]:
        raise ValueError("Native map bytes differ from reviewed source")
    plan = build_plan(geometry, case_id, direction=getattr(operator, "direction", 1))
    scratch_root = Path(os.environ["SCENARIO_PIPELINE_OUTPUT_ROOT"]).resolve()
    if ".runtime-work" not in scratch_root.parts:
        raise ValueError("Native scratch must be under .runtime-work")
    scratch_root.mkdir(parents=True, exist_ok=True)
    root = Path(tempfile.mkdtemp(prefix="c135705-attempt-", dir=scratch_root))
    archives = {}
    started = False
    frames, width_history = [], []
    try:
        _write(root / "alley_geometry.json", geometry)
        (root / "road.xodr").write_bytes(map_bytes)
        operator.start(plan)
        started = True
        actors = operator.read_actor_inventory()
        if actors.get("ego_vehicle_id") != geometry.get("ego_vehicle_id") or not actors.get("ego_actual_blueprint") or not actors.get("ego_actual_dimensions_m"):
            raise ValueError("actual ego actor readback missing")
        if variant.startswith("other_vehicle") and (not actors.get("other_vehicle_id") or not actors.get("other_actual_blueprint") or not actors.get("other_actual_dimensions_m")):
            raise ValueError("actual controlled other vehicle readback missing")
        _write(root / "actor_inventory.json", actors)
        archives = {name: zipfile.ZipFile(root / (name + ".zip"), "w", zipfile.ZIP_STORED)
                    for name in sorted(CAMERAS)}
        for index in range(FRAMES):
            tick = operator.tick()
            frame, time_s = tick.get("frame"), tick.get("time_s")
            if type(frame) is not int or type(time_s) not in (int, float) or not math.isfinite(time_s):
                raise ValueError("original Native frame identity missing")
            if frames and (frame != frames[-1]["frame"] + 1 or abs(time_s - frames[-1]["time_s"] - 0.05) > 0.001):
                raise ValueError("original Native frame gap or cadence drift")
            if after_tick is not None:
                after_tick(frame, time_s)
            row = operator.read_width_history(frame)
            if row.get("frame") != frame or row.get("time_s") != time_s or not row.get("source"):
                raise ValueError("original body width source/frame mismatch")
            if row.get("ego_vehicle_id") != actors["ego_vehicle_id"]:
                raise ValueError("original ego body identity mismatch")
            if variant.startswith("other_vehicle") and row.get("other_vehicle_id") != actors["other_vehicle_id"]:
                raise ValueError("original controlled other body identity mismatch")
            cameras = operator.read_cameras(frame)
            if not isinstance(cameras, dict) or set(cameras) != CAMERAS:
                raise ValueError("four original camera sources missing")
            for name in sorted(CAMERAS):
                packet = cameras[name]
                raw = packet.get("png")
                if packet.get("frame") != frame or packet.get("time_s") != time_s or not isinstance(raw, bytes) or not raw.startswith(b"\x89PNG\r\n\x1a\n"):
                    raise ValueError("original camera frame missing: " + name)
                archives[name].writestr(f"{index:04d}-{frame}.png", raw)
            frames.append({"frame": frame, "time_s": time_s, "video_frame": index})
            width_history.append(row)
        if hashlib.sha256(operator.get_opendrive_bytes()).hexdigest() != geometry["map_sha256"]:
            raise ValueError("original map changed during capture")
        operator.capture_complete = True
    except BaseException:
        shutil.rmtree(root, ignore_errors=True)
        raise
    finally:
        for archive in archives.values():
            archive.close()
        try:
            if started:
                operator.brake()
        finally:
            try:
                operator.cleanup()
            except BaseException:
                shutil.rmtree(root, ignore_errors=True)
                raise
    try:
        sources = {"frame_map": {"frames":frames},
                   "alley_geometry": geometry,
                   "width_history": {"case_id":case_id, "source_kind":"original_native", "samples":width_history}}
        inventory = {"case_id":case_id, "source_kind":"original_native", "frame_count":FRAMES, "sources":{},
                     "diagnostic_fixture":not bool(getattr(operator,"native_attested",False)),
                     "map_sha256":geometry["map_sha256"], "media":{}}
        for name, value in sources.items():
            filename = name + ".json"
            inventory["sources"][name] = {"path":filename,"sha256":_write(root / filename,value)}
        for name in sorted(CAMERAS):
            filename = name + ".zip"
            inventory["media"][name] = {"path":filename,"sha256":hashlib.sha256((root / filename).read_bytes()).hexdigest()}
        if not inventory["diagnostic_fixture"]:
            inventory["physical_completion"] = False
        _write(root / "inventory.json", inventory)
        measurement = measure_saved(root, case_id)
        destination.parent.mkdir(parents=True, exist_ok=True)
        os.replace(root, destination)
        return {"case_id":case_id,"frame_count":FRAMES,
                "minimum_available_continuous_width_ft":measurement["minimum_available_continuous_width_ft"],
                "diagnostic_fixture":inventory["diagnostic_fixture"],
                "free_movement_judgment":"unresolved"}
    except BaseException:
        shutil.rmtree(root, ignore_errors=True)
        raise

"""Low-level route tracking, braking, hold and departure for an alley attempt.

Controls are requests; only Native readback establishes actual parking motion.
"""
from __future__ import annotations

import math


def _point(value):
    if not isinstance(value, (tuple, list)) or len(value) != 2:
        raise ValueError("vehicle position missing")
    x, y = value
    if any(type(a) not in (int, float) or not math.isfinite(a) for a in (x, y)):
        raise ValueError("vehicle position nonfinite")
    return float(x), float(y)


class ParkingController:
    def __init__(self, plan: dict):
        self.plan = plan
        self.phase = "approach"
        self.hold_since = None
        self.target = _point(plan["target_xy_m"])
        self.depart = _point(plan["depart_xy_m"])
        self.axis = _point(plan["route_axis_xy"])
        self.direction = plan["direction"]
        if abs(math.hypot(*self.axis) - 1) > .001 or self.direction not in (-1, 1):
            raise ValueError("invalid surveyed route axis")

    def step(self, *, xy_m, yaw_rad, speed_mps, time_s) -> dict:
        xy = _point(xy_m)
        if any(type(x) not in (int, float) or not math.isfinite(x)
               for x in (yaw_rad, speed_mps, time_s)) or speed_mps < 0:
            raise ValueError("Native vehicle state invalid")
        axis = (self.axis[0] * self.direction, self.axis[1] * self.direction)
        dx, dy = xy[0] - self.target[0], xy[1] - self.target[1]
        remaining = -(dx * axis[0] + dy * axis[1])
        lateral = abs(dx * -axis[1] + dy * axis[0])
        if lateral > 3.0:
            raise ValueError("vehicle left surveyed alley route")
        if self.phase == "approach" and remaining < 1.0:
            self.phase = "braking"
        if self.phase == "braking" and speed_mps <= .1 and math.hypot(dx, dy) <= .75:
            self.phase = "hold"
            self.hold_since = time_s
        if self.phase == "hold" and time_s - self.hold_since >= self.plan["controller"]["hold_min_s"]:
            self.phase = "depart"
        if self.phase == "depart" and math.dist(xy, self.depart) <= 1.0:
            self.phase = "done"
        if self.phase in ("braking", "hold", "done"):
            return {"phase": self.phase, "throttle": 0.0, "brake": 1.0, "steer": 0.0}
        desired_yaw = math.atan2(axis[1], axis[0])
        heading_error = (desired_yaw - yaw_rad + math.pi) % (2 * math.pi) - math.pi
        signed_lateral = dx * -axis[1] + dy * axis[0]
        steer = max(-.45, min(.45, 1.2 * heading_error - .12 * signed_lateral))
        target_speed = min(4.0, max(.8, remaining / 2)) if self.phase == "approach" else 3.0
        throttle = max(0.0, min(.6, .2 * (target_speed - speed_mps)))
        brake = max(0.0, min(.6, .3 * (speed_mps - target_speed)))
        return {"phase": self.phase, "throttle": throttle, "brake": brake, "steer": steer}

"""Measure continuous original alley width; leave legal free movement for review.

The statutory 10-foot boundary is exact. This module measures physical free
cross-section intervals from surveyed boundaries and original body polygons. It
does not decide whether a vehicle could move freely or an ordinance applies.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT = "testing__C135705__NRS-484B-477-1b__motor_vehicle_driver"
FEET_PER_M = 3.280839895013123


def _point(value, label):
    if not isinstance(value, (list, tuple)) or len(value) != 2 or any(
            type(x) not in (int, float) or not math.isfinite(x) for x in value):
        raise ValueError(label + " must have two finite coordinates")
    return (float(value[0]), float(value[1]))


def _polygon(value, label):
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError(label + " polygon missing")
    return [_point(p, label) for p in value]


def _cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def _inside(point, polygon):
    inside = False
    x, y = point
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > y) != (b[1] > y):
            crossing_x = a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if crossing_x > x:
                inside = not inside
    return inside


def _blocked_interval(left, right, polygon):
    """Return cross-section parameters inside a polygon, including tangencies."""
    direction = (right[0] - left[0], right[1] - left[1])
    lengthsq = direction[0] ** 2 + direction[1] ** 2
    if lengthsq <= 1e-8:
        raise ValueError("alley cross-section has zero width")
    hits = []
    if _inside(left, polygon):
        hits.append(0.0)
    if _inside(right, polygon):
        hits.append(1.0)
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        edge = (b[0] - a[0], b[1] - a[1])
        offset = (a[0] - left[0], a[1] - left[1])
        determinant = _cross(direction, edge)
        if abs(determinant) < 1e-12:
            if abs(_cross(offset, direction)) < 1e-9:
                hits.extend(((a[0] - left[0]) * direction[0] +
                             (a[1] - left[1]) * direction[1]) / lengthsq for _ in (0,))
                hits.append(((b[0] - left[0]) * direction[0] +
                             (b[1] - left[1]) * direction[1]) / lengthsq)
            continue
        along = _cross(offset, edge) / determinant
        on_edge = _cross(offset, direction) / determinant
        if -1e-9 <= on_edge <= 1 + 1e-9 and -1e-9 <= along <= 1 + 1e-9:
            hits.append(max(0.0, min(1.0, along)))
    if not hits:
        return None
    return (min(hits), max(hits))


def continuous_free_width_m(left, right, bodies):
    left, right = _point(left, "left boundary"), _point(right, "right boundary")
    span = math.dist(left, right)
    intervals = []
    for i, body in enumerate(bodies):
        hit = _blocked_interval(left, right, _polygon(body, "body " + str(i)))
        if hit is not None and hit[1] > hit[0]:
            intervals.append(hit)
    intervals.sort()
    cursor = 0.0
    gaps = []
    for low, high in intervals:
        if low > cursor:
            gaps.append((cursor, low))
        cursor = max(cursor, high)
    if cursor < 1.0:
        gaps.append((cursor, 1.0))
    return span * max((high - low for low, high in gaps), default=0.0)


def _require_source(value, label):
    if not isinstance(value, dict) or not value.get("path") or not isinstance(value.get("sha256"), str) or len(value["sha256"]) != 64:
        raise ValueError(label + " source hash missing")


def measure(case_id, geometry, history, *, expected_frames=900):
    if not case_id.startswith(ASSIGNMENT + "__") or geometry.get("case_id") != case_id:
        raise ValueError("wrong exact alley-width identity")
    if geometry.get("alley_kind") != "other_alley" or geometry.get("public_highway_status") is not True:
        raise ValueError("any other alley source classification missing")
    for key in ("public_highway_source", "city_block_source", "rear_access_source",
                "abutting_property_source", "through_connection_source", "jurisdiction_source",
                "ordinance_source", "survey_source"):
        _require_source(geometry.get(key), key)
    if geometry.get("cul_de_sac") is not False or geometry.get("start_connected") is not True or geometry.get("end_connected") is not True:
        raise ValueError("connected non-cul-de-sac alley not established")
    if geometry.get("ordinance_status") not in ("none_found", "otherwise_provides", "unresolved"):
        raise ValueError("reviewed ordinance status missing")
    sections = geometry.get("cross_sections")
    if not isinstance(sections, list) or len(sections) < 2:
        raise ValueError("surveyed alley cross-sections missing")
    stations = []
    for section in sections:
        if type(section.get("station_m")) not in (int, float):
            raise ValueError("cross-section station missing")
        _point(section.get("left_xy_m"), "left boundary")
        _point(section.get("right_xy_m"), "right boundary")
        _require_source(section.get("source"), "cross-section")
        stations.append(float(section["station_m"]))
    if stations != sorted(set(stations)):
        raise ValueError("cross-section stations must be unique and ordered")
    if not isinstance(history, list) or len(history) != expected_frames:
        raise ValueError("original 20 Hz frame history incomplete")
    if [r.get("frame") for r in history] != list(range(history[0].get("frame", -1), history[0].get("frame", -1) + expected_frames)):
        raise ValueError("original frame sequence has a gap")
    for previous, current in zip(history, history[1:]):
        if (type(current.get("time_s")) not in (int, float) or
                type(previous.get("time_s")) not in (int, float) or
                abs(current["time_s"] - previous["time_s"] - 0.05) > 0.001):
            raise ValueError("original 20 Hz width history cadence differs")
    held = []
    for row in history:
        _require_source(row.get("source"), "original frame")
        if row.get("phase") != "parked_hold":
            continue
        ego = _polygon(row.get("ego_body_polygon_m"), "ego body")
        others = [_polygon(body, "other body") for body in row.get("other_body_polygons_m", [])]
        if case_id.rsplit("__", 1)[-1].startswith("other_vehicle") and not others:
            raise ValueError("controlled other vehicle original body missing")
        widths = [continuous_free_width_m(section["left_xy_m"], section["right_xy_m"],
                                          [ego, *others]) * FEET_PER_M for section in sections]
        held.append({"frame": row["frame"], "minimum_continuous_width_ft": round(min(widths), 6),
                     "section_widths_ft": [round(width, 6) for width in widths],
                     "other_vehicle_count": len(others)})
    if not held:
        raise ValueError("original parked hold absent")
    return {"case_id": case_id, "source_classification": "other_alley",
            "ordinance_status": geometry["ordinance_status"],
            "minimum_available_continuous_width_ft": min(r["minimum_continuous_width_ft"] for r in held),
            "statutory_less_than_10_ft_observed": min(r["minimum_continuous_width_ft"] for r in held) < 10.0,
            "held_samples": held, "free_vehicular_movement_judgment": "unresolved",
            "ordinance_applicability_judgment": "unresolved",
            "source_sha256": hashlib.sha256(json.dumps(geometry,sort_keys=True).encode()).hexdigest()}


def measure_saved(attempt, case_id, *, expected_frames=900):
    """Reopen sealed original packet bytes; reject missing or changed sources."""
    root = Path(attempt)
    inventory = json.loads((root / "inventory.json").read_text())
    if inventory.get("case_id") != case_id or inventory.get("source_kind") != "original_native":
        raise ValueError("original alley-width inventory identity missing")
    packets = {}
    for name in ("alley_geometry", "width_history", "frame_map"):
        ref = inventory.get("sources", {}).get(name)
        if not isinstance(ref, dict) or ref.get("path") != name + ".json":
            raise ValueError("original " + name + " packet missing")
        raw = (root / ref["path"]).read_bytes()
        if hashlib.sha256(raw).hexdigest() != ref.get("sha256"):
            raise ValueError("original " + name + " packet hash changed")
        packets[name] = json.loads(raw)
    joined = packets["frame_map"].get("frames")
    history = packets["width_history"].get("samples")
    if not isinstance(joined, list) or not isinstance(history, list) or len(joined) != expected_frames:
        raise ValueError("original width frame map incomplete")
    if [(r.get("frame"), r.get("time_s")) for r in joined] != [
            (r.get("frame"), r.get("time_s")) for r in history]:
        raise ValueError("original width history/frame time join differs")
    return measure(case_id, packets["alley_geometry"], history,
                   expected_frames=expected_frames)

